421	/// Deal damage from a source creature to a target creature. Handles lifelink.
422	fn deal_damage_to_creature(
423	    state: &mut GameState,
424	    source: ObjectId,
425	    target: ObjectId,
426	    amount: u32,
427	    registry: &CardRegistry,
428	) {
429	    // Skip if source or target has combat damage prevention (e.g., Ghostly Possession).
430	    if has_damage_prevention(state, source, registry) || has_damage_prevention(state, target, registry) {
431	        return;
432	    }
433	
434	    // Moonmist: prevent combat damage from non-Wolf/non-Werewolf creatures.
435	    if is_non_wolf_damage_prevented(state, source, registry) {
436	        return;
437	    }
438	
439	    // Protection: if target has protection from the source creature, prevent damage.
440	    if has_protection_from_creature(state, target, source, registry) {
441	        return;
442	    }
443	
444	    // Unbreathing Horde: prevent damage, remove counter.
445	    if apply_prevent_damage_remove_counter(state, target, registry) {
446	        return;
447	    }
448	
449	    // Inquisitor's Flail: multiply damage for each DoubleCombatDamage source.
450	    // Dealing: source's Flails multiply the damage dealt.
451	    // Receiving: target's Flails multiply the damage received.
452	    let mut amount = amount;
453	    amount *= combat_damage_multiplier(state, source, registry);
454	    amount *= combat_damage_multiplier(state, target, registry);
455	
456	    let has_deathtouch = state.has_keyword(source, Keyword::Deathtouch, registry);
457	    if let Some(obj) = state.get_object_mut(target) {
458	        obj.damage_marked += amount;
459	        if has_deathtouch {
460	            obj.dealt_deathtouch_damage = true;
461	        }
462	        // Track which creatures dealt damage to this creature (for Abattoir Ghoul).
463	        if !obj.damaged_by.contains(&source) {
464	            obj.damaged_by.push(source);
465	        }
466	    }
467	    state.events.push(GameEvent::CombatDamageDealt {
468	        source,
469	        target: DamageTarget::Object(target),
470	        amount,
471	    });
472	
473	    // Lifelink: source's controller gains life.
474	    if state.has_keyword(source, Keyword::Lifelink, registry) {
475	        let controller = state.get_object(source).expect("damage source must exist").controller;
476	        let old_life = state.get_player(controller).life;
477	        let new_life = old_life + amount as i32;
478	        state.get_player_mut(controller).life = new_life;
479	        state.events.push(GameEvent::LifeChanged {
480	            player: controller,
481	            old: old_life,
482	            new_life,
483	        });
484	    }
485	}
486	
487	/// Deal damage from a source creature to a player. Handles lifelink.
488	fn deal_damage_to_player(
489	    state: &mut GameState,
490	    source: ObjectId,
491	    player: PlayerId,
492	    amount: u32,
493	    registry: &CardRegistry,
494	) {
495	    // Skip if source has combat damage prevention (e.g., Ghostly Possession).
496	    if has_damage_prevention(state, source, registry) {
497	        return;
498	    }
499	
500	    // Moonmist: prevent combat damage from non-Wolf/non-Werewolf creatures.
501	    if is_non_wolf_damage_prevented(state, source, registry) {
502	        return;
503	    }
504	
505	    // Inquisitor's Flail: multiply damage for each DoubleCombatDamage source.
506	    let mut amount = amount;
507	    amount *= combat_damage_multiplier(state, source, registry);
508	
509	    let old_life = state.get_player(player).life;
510	    let new_life = old_life - amount as i32;
511	    state.get_player_mut(player).life = new_life;
512	
513	    state.events.push(GameEvent::CombatDamageDealt {
514	        source,
515	        target: DamageTarget::Player(player),
516	        amount,
517	    });
518	    state.events.push(GameEvent::LifeChanged {
519	        player,
520	        old: old_life,
521	        new_life,
522	    });
523	
524	    let name = state.get_object(source)
525	        .map(|o| {
526	            // Use object name directly (works for tokens); fall back to registry.
527	            if !o.name.is_empty() {
528	                o.name.clone()
529	            } else {
530	                registry.card_data(o.card_id)
531	                    .map(|d| d.name)
532	                    .unwrap_or_else(|| "?".into())
533	            }
534	        })
535	        .unwrap_or_else(|| "?".into());
536	    state.log(LogLevel::Event, format!("p{} took {} combat damage ({}) from {}", player.0, amount, new_life, name));
537	
538	    // Lifelink: source's controller gains life.
539	    if state.has_keyword(source, Keyword::Lifelink, registry) {
540	        let controller = state.get_object(source).expect("damage source must exist").controller;
541	        let old = state.get_player(controller).life;
542	        let new = old + amount as i32;
543	        state.get_player_mut(controller).life = new;
544	        state.events.push(GameEvent::LifeChanged {
545	            player: controller,
546	            old,
547	            new_life: new,
548	        });
549	    }
550	}
