13	/// Perform state-based actions. Returns true if any were performed.
14	/// Per rule 704.3, this is called repeatedly until no actions are taken.
15	pub fn check_state_based_actions_with_registry(state: &mut GameState, registry: Option<&CardRegistry>) -> bool {
16	    let mut any_action = false;
17	
18	    loop {
19	        let mut took_action = false;
20	
21	        // Rule 704.5a: A player with 0 or less life loses the game.
22	        for i in 0..state.players.len() {
23	            let (lost, life, id) = {
24	                let p = &state.players[i];
25	                (p.lost, p.life, p.id)
26	            };
27	            if !lost && life <= 0 {
28	                state.players[i].lost = true;
29	                state.events.push(GameEvent::PlayerLost {
30	                    player: id,
31	                    reason: LossReason::LifeReachedZero,
32	                });
33	                took_action = true;
34	            }
35	        }
36	
37	        // Rule 704.5b: A player who attempted to draw from an empty library loses.
38	        for i in 0..state.players.len() {
39	            let (lost, drawn_empty, id) = {
40	                let p = &state.players[i];
41	                (p.lost, p.has_drawn_from_empty, p.id)
42	            };
43	            if !lost && drawn_empty {
44	                state.players[i].lost = true;
45	                state.events.push(GameEvent::PlayerLost {
46	                    player: id,
47	                    reason: LossReason::DrewFromEmptyLibrary,
48	                });
49	                took_action = true;
50	            }
51	        }
52	
53	        // Identify creatures that need to leave the battlefield.
54	        let creature_ids: Vec<_> = state.objects.values()
55	            .filter(|o| o.zone == Zone::Battlefield && o.power.is_some())
56	            .map(|o| o.id)
57	            .collect();
58	
59	        // Classify each creature: zero toughness vs lethal damage/deathtouch.
60	        let mut zero_toughness_ids = Vec::new();
61	        let mut destroyed_ids = Vec::new();
62	
63	        for id in creature_ids {
64	            let effective_t = registry
65	                .and_then(|r| state.effective_toughness(id, r))
66	                .or_else(|| state.get_object(id).and_then(|o| o.toughness));
67	            let obj = state.get_object(id);
68	            let damage = obj.map(|o| o.damage_marked).unwrap_or(0);
69	            let deathtouch = obj.map(|o| o.dealt_deathtouch_damage).unwrap_or(false);
70	            match effective_t {
71	                Some(t) if t <= 0 => {
72	                    // Rule 704.5f: 0 or less toughness — not destruction,
73	                    // indestructible and regeneration do NOT prevent this.
74	                    zero_toughness_ids.push(id);
75	                }
76	                Some(t) if (damage as i32) >= t || (deathtouch && damage > 0) => {
77	                    // Rules 704.5g/h: lethal damage or deathtouch — destruction,
78	                    // checked via try_destroy (indestructible / regeneration apply).
79	                    destroyed_ids.push(id);
80	                }
81	                _ => {}
82	            }
83	        }
84	
85	        // Rule 704.5f: zero toughness goes directly to graveyard.
86	        for id in zero_toughness_ids {
87	            let (cid, ctrl, damaged_by) = state.get_object(id)
88	                .map(|o| (o.card_id, o.controller, o.damaged_by.clone()))
89	                .unwrap_or((crate::ids::CardId(0), crate::ids::PlayerId(0), Vec::new()));
90	            let last_known_toughness = registry
91	                .and_then(|r| state.effective_toughness(id, r))
92	                .or_else(|| state.get_object(id).and_then(|o| o.toughness))
93	                .unwrap_or(0);
94	            state.events.push(GameEvent::CreatureDied { object: id, card_id: cid, controller: ctrl, damaged_by, last_known_toughness });
95	            state.move_object(id, Zone::Graveyard);
96	            state.creature_died_this_turn = true;
97	            took_action = true;
98	        }
99	
100	        // Rules 704.5g/h: lethal damage or deathtouch — use destruction pipeline.
101	        for id in destroyed_ids {
102	            if let Some(reg) = registry {
103	                use crate::destruction::DestroyResult;
104	                // Full pipeline: indestructible check + regeneration.
105	                match crate::destruction::try_destroy(state, id, reg) {
106	                    DestroyResult::Died => {
107	                        took_action = true;
108	                    }
109	                    DestroyResult::Regenerated => {
110	                        // State changed (damage cleared, tapped), so next
111	                        // SBA pass won't re-identify this creature.
112	                        took_action = true;
113	                        continue;
114	                    }
115	                    DestroyResult::Indestructible => {
116	                        // No state change — don't set took_action to avoid
117	                        // infinite loop (creature still has lethal damage).
118	                        continue;
119	                    }
120	                }
121	            } else {
122	                // No registry (legacy tests): skip indestructible check,
123	                // but still handle regeneration shields inline.
124	                let shields = state.get_object(id).map(|o| o.regeneration_shields).unwrap_or(0);
125	                if shields > 0 {
126	                    crate::destruction::remove_from_combat(state, id);
127	                    if let Some(obj) = state.get_object_mut(id) {
128	                        obj.tapped = true;
129	                        obj.damage_marked = 0;
130	                        obj.dealt_deathtouch_damage = false; obj.damaged_by.clear();
131	                        obj.regeneration_shields -= 1;
132	                    }
133	                    state.log(LogLevel::Event, format!("{} regenerated",
134	                        state.get_object(id).map(|o| o.name.as_str()).unwrap_or("?")));
135	                    took_action = true;
136	                    continue;
137	                }
138	                let (cid, ctrl, damaged_by) = state.get_object(id)
139	                    .map(|o| (o.card_id, o.controller, o.damaged_by.clone()))
140	                    .unwrap_or((crate::ids::CardId(0), crate::ids::PlayerId(0), Vec::new()));
141	                let last_known_toughness = state.get_object(id).and_then(|o| o.toughness).unwrap_or(0);
142	                state.events.push(GameEvent::CreatureDied { object: id, card_id: cid, controller: ctrl, damaged_by, last_known_toughness });
143	                state.move_object(id, Zone::Graveyard);
144	                state.creature_died_this_turn = true;
145	                took_action = true;
146	            }
147	        }
148	
149	        // Rule 704.5m: Aura not attached to anything goes to graveyard.
150	        // Curses attached to players (attached_to_player) are exempt.
151	        // Equipment stays on the battlefield when unattached (detaches instead).
152	        let unattached_auras: Vec<_> = state.objects.values()
153	            .filter(|o| {
154	                o.zone == Zone::Battlefield
155	                    && o.attached_to.is_some()
156	                    && o.attached_to_player.is_none() // player-attached curses are fine
157	                    && !o.is_equipment // equipment stays on battlefield when unattached
158	                    && {
159	                        let target_id = o.attached_to.expect("aura must have attached_to");
160	                        state.get_object(target_id)
161	                            .map(|t| t.zone != Zone::Battlefield)
162	                            .unwrap_or(true) // target doesn't exist
163	                    }
164	            })
165	            .map(|o| o.id)
166	            .collect();
167	
168	        // Equipment attached to creatures that left the battlefield: detach (don't destroy).
169	        let detach_equipment: Vec<ObjectId> = state.objects.values()
170	            .filter(|o| {
171	                o.zone == Zone::Battlefield
172	                    && o.is_equipment
173	                    && o.attached_to.is_some()
174	                    && {
175	                        let target_id = o.attached_to.expect("equipment must have attached_to");
176	                        state.get_object(target_id)
177	                            .map(|t| t.zone != Zone::Battlefield)
178	                            .unwrap_or(true)
179	                    }
180	            })
181	            .map(|o| o.id)
182	            .collect();
183	        for id in detach_equipment {
184	            if let Some(obj) = state.get_object_mut(id) {
185	                obj.attached_to = None;
186	            }
187	            took_action = true;
188	        }
